import test from 'node:test';
import assert from 'node:assert/strict';
import {label} from '../src/label.mjs';
test('lowercase label',()=>assert.equal(label('  Hello World  '),'hello-world'));
test('whitespace',()=>assert.equal(label('a   b'),'a-b'));
test('empty input',()=>assert.equal(label('  '),''));

import test from 'node:test';
import assert from 'node:assert/strict';
import {available} from '../src/area.mjs';
import {fit} from '../src/fit.mjs';
import {layout} from '../src/layout.mjs';
test('reserved margins',()=>assert.equal(available(720,10,10),700));
test('small width',()=>assert.equal(fit(700,1280),700));
test('large width',()=>assert.equal(fit(460,320),320));
test('integration',()=>assert.equal(layout(800,720,10,10),700));

import {available} from './area.mjs';
import {fit} from './fit.mjs';
export function layout(width, screen, left, right) { return fit(width, available(screen, left, right)); }

